test('GPU delta pass agrees numerically with the anchored plain-JS oracle', async ({ page }) => {
  await openSim(page, 'field=64&cap=32&seed=0&paused=1');
  const result = await page.evaluate(async () => {
    const sim = window.__v2.sim;
    Object.assign(sim.params, {
      fieldDiffusion: 0,
      fieldDecay: 1,
      uptakeRate: 0.035,
      depositRate: 0.005,
      burnRate: 0.005,
      deltaScale: 1.35,
      foodClamp: 0.5,
      stepSize: 0,
      wander: 0,
      sensorDistance: 0,
      reproThreshold: 4.5,
      maxReserve: 4.2,
    });
    sim.clearOats();
    let randomState = 0x6d3f_27a1;
    const unitRandom = () => {
      randomState = (Math.imul(randomState, 1_664_525) + 1_013_904_223) >>> 0;
      return randomState / 0x1_0000_0000;
    };
    const samples = Array.from({ length: 24 }, (_, index) => ({
      x: 4 + (index % 6) * 10,
      y: 5 + Math.floor(index / 6) * 14,
      food: 0.02 + unitRandom() * 0.47,
      reserve: 0.1 + unitRandom() * 4,
    }));
    const field = new Float32Array(64 * 64);
    const agents = samples.map((sample, index) => {
      field[sample.y * 64 + sample.x] = sample.food;
      return {
        uvPos: [(sample.x + 0.5) / 64, (sample.y + 0.5) / 64],
        heading: 0,
        reserve: sample.reserve,
        idLo: index + 1,
        idHi: 5,
        flags: 0,
      };
    });
    await sim.debugReplaceState({ agents, field });
    sim.step(0.75);
    const gpuField = await sim.readField();
    return {
      params: { ...sim.params },
      samples: samples.map((sample) => ({ ...sample, gpu: gpuField[sample.y * 64 + sample.x] })),
    };
  });
  for (const sample of result.samples) {
    const sampledFood = Math.fround(sample.food);
    const startingReserve = Math.fround(sample.reserve);
    const finalReserve = Math.min(result.params.maxReserve,
      startingReserve + (result.params.uptakeRate * sampledFood
        - result.params.depositRate - result.params.burnRate) * 0.75);
    const fixedDensity = Math.round(finalReserve * 0.032 * 4096) / 4096;
    const expected = resolveFoodDelta({
      food: sampledFood,
      density: fixedDensity,
      uptakeRate: result.params.uptakeRate,
      depositRate: result.params.depositRate,
      deltaScale: result.params.deltaScale,
      dt: 0.75,
      foodClamp: result.params.foodClamp,
    });
    expect(sample.gpu).toBeCloseTo(expected, 5);
  }
});

test('oats max-compose, clear immediately, ration, and honor all 64 records', async ({ page }) => {
  await openSim(page, 'field=64&cap=8&seed=0&paused=1');
  const result = await page.evaluate(async () => {
    const sim = window.__v2.sim;
    sim.setOats([
      { uvPos: [32.5 / 64, 32.5 / 64], radiusUv: 0.01, peakFood: 0.3 },
      { uvPos: [32.5 / 64, 32.5 / 64], radiusUv: 0.01, peakFood: 0.6 },
    ]);
    sim.step(0);
    const overlap = (await sim.readOatField())[32 * 64 + 32];
    sim.setOats([{ uvPos: [0.5, 0.5], radiusUv: 0.1, peakFood: 1 }]);
    sim.step(0);
    const outsideSupport = (await sim.readOatField())[0];
    sim.clearOats();
    sim.step(0);
    const clearedMax = Math.max(...await sim.readOatField());
    const oats = Array.from({ length: 64 }, (_, index) => ({
      uvPos: [((index % 8) * 8 + 0.5) / 64, (Math.floor(index / 8) * 8 + 0.5) / 64],
      radiusUv: 0.001,
      peakFood: 0.1 + index * 0.005,
    }));
    sim.setOats(oats);
    sim.step(0);
    const honored = sim.oats().length;
    const oatField = await sim.readOatField();
    const lastOat = oatField[56 * 64 + 56];

    const reserveAfter = async (rationing) => {
      sim.setOats([{ uvPos: [0.5, 0.5], radiusUv: 0.02, peakFood: 0.8 }]);
      Object.assign(sim.params, {
        useOatRationing: rationing,
        oatSupplyRate: 0.001,
        uptakeRate: 0.09,
        depositRate: 0,
        burnRate: 0,
        stepSize: 0,
        wander: 0,
        sensorDistance: 0,
        reproThreshold: 4.5,
      });
      await sim.debugReplaceState({
        agents: [{ uvPos: [0.5, 0.5], heading: 0, reserve: 2, idLo: 1, idHi: 1, flags: 0 }],
      });
      sim.step(1);
      return (await sim.readAgents())[0].reserve;
    };
    return {
      overlap,
      outsideSupport,
      clearedMax,
      honored,
      lastOat,
      rationed: await reserveAfter(true),
      full: await reserveAfter(false),
    };
  });
  expect(result.overlap).toBeCloseTo(0.6, 4);
  expect(result.outsideSupport).toBe(0);
  expect(result.clearedMax).toBe(0);
  expect(result.honored).toBe(64);
  expect(result.lastOat).toBeCloseTo(0.415, 4);
  expect(result.full).toBeGreaterThan(result.rationed);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { createParams } from '../../src/shared/params.js';
import {
  createPopulationControllerState,
  updatePopulationController,
} from '../../src/sim/controller.js';
import { rationedOatFood, resolveFoodDelta } from '../../src/sim/delta-oracle.js';
import { createSimulationTimebase } from '../../src/sim/timebase.js';

test('delta oracle preserves exposure normalization, cap, dt, and output clamp', () => {
  const state = {
    food: 0.42,
    density: 0.032 * 80,
    uptakeRate: 0.035,
    depositRate: 0.005,
    deltaScale: 1.35,
    dt: 0.75,
    foodClamp: 0.5,
  };
  const exposure = 64 * state.deltaScale * state.dt;
  const expected = Math.min(0.5, Math.max(0,
    state.food + state.depositRate * exposure - state.food * (1 - Math.exp(-state.uptakeRate * exposure)),
  ));
  assert.equal(resolveFoodDelta(state), expected);
  assert.notEqual(resolveFoodDelta(state), resolveFoodDelta({ ...state, density: 0.032 * 8 }));
});

test('oat rationing follows local reserve load and can be disabled', () => {
  const input = { oatFood: 1, localDensity: 0.32, uptakeRate: 0.035, oatSupplyRate: 0.14 };
  assert.equal(rationedOatFood({ ...input, enabled: false }), 1);
  assert.ok(rationedOatFood(input) < 1);
  assert.ok(rationedOatFood({ ...input, localDensity: 0.032 }) > rationedOatFood(input));
});

test('population controller honors sample timing, log command, EMA, deadband, and bounds', () => {
  const params = createParams({
    usePopulationControl: true,
    populationTarget: 1000,
    oatSupplyRate: 0.14,
    populationControlPeriodMs: 1200,
  });
  const state = createPopulationControllerState(params);
  const first = updatePopulationController(params, state, { now: 0, visibleAgents: 1000 });
  assert.equal(first.samples.length, 0);
  assert.equal(params.oatSupplyRate, 0.14);
  updatePopulationController(params, state, { now: 600, visibleAgents: 1200 });
  assert.equal(state.lastSampleTime, 0);
  const second = updatePopulationController(params, state, { now: 1200, visibleAgents: 1200 });
  assert.equal(second.samples.length, 1);
  assert.ok(second.growthRate > 0);
  assert.ok(second.commandedGrowthRate < 0);
  assert.ok(params.oatSupplyRate < 0.14);
  const growthBefore = second.growthRate;
  const third = updatePopulationController(params, state, { now: 2400, visibleAgents: 1200 });
  assert.ok(third.growthRate < growthBefore);
  assert.ok(third.growthRate > 0);

  params.populationTarget = 1190;
  const deadbanded = updatePopulationController(params, state, { now: 3600, visibleAgents: 1200 });
  assert.equal(Math.abs(deadbanded.commandedGrowthRate), 0);
  assert.ok(params.oatSupplyRate >= params.populationOatSupplyMin);
  assert.ok(params.oatSupplyRate <= params.populationOatSupplyMax);
});

test('secondary actuator is stateful and only engages at the low supply bound', () => {
  const params = createParams({
    usePopulationControl: true,
    populationTarget: 1000,
    oatSupplyRate: 0.001,
    populationUseSecondaryActuator: true,
  });
  const state = createPopulationControllerState(params);
  updatePopulationController(params, state, { now: 0, visibleAgents: 1500 });
  updatePopulationController(params, state, { now: 1200, visibleAgents: 1700 });
  assert.equal(state.saturatedLow, true);
  assert.ok(state.secondarySeverity > 0);
  assert.ok(params.burnRate > state.baseBurnRate);
  assert.ok(params.reproThreshold > state.baseReproThreshold);
});

test('legacy and fixed-tick timebases expose their deliberately different laws', () => {
  const legacy = createSimulationTimebase();
  assert.deepEqual(legacy.frame(33.3334, 2), [1, 1]);
  assert.deepEqual(legacy.frame(1000, 1), [2.2]);
  const fixed = createSimulationTimebase({ fixedTick: true });
  assert.deepEqual(fixed.frame(8, 2), []);
  assert.deepEqual(fixed.frame(9, 2), [0.5, 0.5]);
});
